import { Global, Inject, Logger, Module, OnApplicationShutdown, OnModuleInit } from '@nestjs/common';
import { drizzle } from 'drizzle-orm/mysql2';
import { migrate } from 'drizzle-orm/mysql2/migrator';
import { createPool, type Pool } from 'mysql2/promise';
import { join } from 'node:path';
import { AppConfig } from '../config/app-config.service';
import { DATABASE, DB_POOL, type Database } from './database';
import * as schema from './schema';

/** Migrations generated by drizzle-kit; webpack copies them next to `main.js`. */
export const MIGRATIONS_FOLDER = join(__dirname, 'drizzle');

@Global()
@Module({
  providers: [
    {
      provide: DB_POOL,
      inject: [AppConfig],
      useFactory: (config: AppConfig) => createPool(config.get('DATABASE_URL')),
    },
    {
      provide: DATABASE,
      inject: [DB_POOL],
      useFactory: (pool: Pool): Database => drizzle({ client: pool, schema, mode: 'default' }),
    },
  ],
  exports: [DATABASE, DB_POOL],
})
export class DatabaseModule implements OnModuleInit, OnApplicationShutdown {
  private readonly logger = new Logger('Database');

  constructor(
    @Inject(DB_POOL) private readonly pool: Pool,
    @Inject(DATABASE) private readonly db: Database,
    @Inject(AppConfig) private readonly config: AppConfig,
  ) {}

  async onModuleInit(): Promise<void> {
    if (!this.config.get('DB_MIGRATE_ON_START')) return;
    this.logger.log('Applying migrations …');
    await migrate(this.db, { migrationsFolder: MIGRATIONS_FOLDER });
    this.logger.log('Migrations up to date');
  }

  async onApplicationShutdown(): Promise<void> {
    await this.pool.end();
  }
}
